seedE_F2.definitions:
def sf2N (μ κ x : ℕ) : ℕ := (μ + κ - 2 - x) / (2 * κ)

def sf2Q (μ κ x : ℕ) : ℕ := (μ - 2 - x) / (2 * κ)

def sf2Rho (μ κ x : ℕ) : ℕ := (μ - 2 - x) % (2 * κ)

def sf2Up (μ κ r : ℕ) : List ℕ :=
  [2 * (r + 1 + 2 * μ), 2 * (r + 1 + μ), 2 * (r + 1), 2 * r + 1, 2 * (r + μ + κ) + 1,
    2 * (r + 2 * μ + 2 * κ) + 1]

def sf2Open (μ κ x : ℕ) : List ℕ := [2 * x, 2 * (x + μ), 2 * (x + μ) + 1, 2 * (x + 2 * μ + κ) + 1]

def sf2Fin (μ κ x : ℕ) : List ℕ := [2 * (x + 2 * μ + 2 * κ) + 1, 2 * (x + μ + κ) + 1, 2 * x + 1]

def sf2Mid (μ κ x : ℕ) : ℕ :=
  if sf2Rho μ κ x < κ then 2 * (2 * μ + κ - 1 - sf2Rho μ κ x)
  else 2 * (2 * μ + 2 * κ - 1 - sf2Rho μ κ x)

def sf2Turn (μ κ x : ℕ) : List ℕ :=
  [2 * (x + κ + 1 + 2 * κ * sf2N μ κ x + 2 * μ), sf2Mid μ κ x,
    2 * (x + 2 * κ * sf2Q μ κ x + 2 * μ + 2 * κ) + 2]

def sf2Round (μ κ x : ℕ) : List ℕ :=
  sf2Open μ κ x ++ (List.range (sf2N μ κ x)).flatMap (fun i => sf2Up μ κ (x + κ + 2 * κ * i)) ++
    sf2Turn μ κ x ++
    (List.range (sf2Q μ κ x)).reverse.flatMap (fun i => (sf2Up μ κ (x + 2 * κ * (i + 1))).reverse) ++
    sf2Fin μ κ x

def sf2Tail (μ κ : ℕ) : List ℕ :=
  [2 * κ, 2 * (μ + κ), 2 * (2 * μ + κ), 2 * (3 * μ + 2 * κ), 2 * (3 * μ + 2 * κ) - 1,
    2 * (2 * μ + κ) - 1, 2 * μ - 1]

def sf2S (μ κ : ℕ) : ℕ := ((List.range κ).map (fun x => sf2N μ κ x + sf2Q μ κ x)).sum

def seedF2List (μ κ : ℕ) : List ℕ := (List.range κ).flatMap (sf2Round μ κ) ++ sf2Tail μ κ

