def ldvBlock (μ q : ℕ) : List ℕ := [2 * μ + 2 * q, 2 * q, 2 * q + 1, 2 * μ + 2 * q + 1]

def ldvZR (μ t n : ℕ) : List ℕ := (List.range n).flatMap (fun i => ldvBlock μ (t + i))

def ldvUnit (μ κ i : ℕ) : List ℕ :=
  [4 * μ + 2 * κ + 2 * i + 4, 4 * μ + 2 * κ + 2 * i + 3, 2 * μ + 2 * i + 2,
   4 * μ + 2 * i + 2, 4 * μ + 2 * i + 1, 2 * μ + 2 * i + 1]

def ldvUnits (μ κ s : ℕ) : List ℕ := (List.range s).reverse.flatMap (ldvUnit μ κ)

def ldvRun (c N : ℕ) : List ℕ := (List.range N).map (fun i => c - i)

def ldvList (μ κ t n s N : ℕ) : List ℕ :=
  (4 * μ + 2 * κ + 2 * t + 1) :: (ldvZR μ t n ++ (4 * μ :: 2 * μ :: (List.range (2 * t) ++
    (2 * μ + 2 * t - 1) :: (ldvUnits μ κ s ++ ldvRun (4 * μ + 2 * κ + 2) N))))

